# Вариант В: транспорт и онлайн-магазин. Формат задачи см. build.py
V = 'C'
TASKS = [
dict(n=1, pts=0.5, title='Проезд по зонам', topics='if / elif / else, in, or',
 text='В окне уже заданы список `zones` и три фразы: `free_msg`, `pay_msg`, `other_msg`. Вводятся зона и возраст пассажира.\n\nЕсли такой зоны нет в списке, напечатайте `other_msg`. Если зона есть и пассажиру меньше 7 лет или 65 и больше, напечатайте `free_msg`. Во всех остальных случаях напечатайте `pay_msg`.',
 fin='Первая строка — зона, вторая — возраст (целое число).', fout='Одна из трёх фраз.',
 pre="zones = ['A', 'B', 'C']\nfree_msg = 'Проезд бесплатный'\npay_msg = 'Оплатите проезд'\nother_msg = 'Такой зоны нет'",
 inputs=[['A','5'],['B','30'],['D','10'],['C','65'],['A','7'],['B','64'],['C','6']],
 sol="zone = input()\nage = int(input())\n\nif zone not in zones:\n    print(other_msg)\nelif age < 7 or age >= 65:\n    print(free_msg)\nelse:\n    print(pay_msg)\n",
 hint='Сначала отсеките несуществующие зоны (`not in`), потом проверьте возраст через `or`, остальное — `else`. Возраст — строка, нужен `int`.',
 idea='Три исхода — цепочка `if / elif / else`: нет зоны; льгота по возрасту; обычный проезд.',
 steps=['`zone = input()` читает зону, `age = int(input())` читает возраст и сразу делает его числом.','`zone not in zones` — первая проверка: если зоны нет, возраст не важен.','`age < 7 or age >= 65` — льгота, если верно **хотя бы одно** из двух условий.','`else` — обычный проезд.'],
 mist=['Написали `age < 7 and age >= 65`: оба условия сразу не бывают верны, льготы не будет ни у кого.','Забыли `int(...)`: сравнение строки с числом — ошибка `TypeError`.','Границы: 7 лет уже платят, 65 лет — ещё бесплатно; перепутали `<` и `<=`.']),
dict(n=2, pts=1, title='Быстрые рейсы', topics='while True, break, split, список',
 text='Вводятся строки вида `рейс:минут` (время в пути, целое число), пока не будет введено слово `END`.\n\nНапечатайте список рейсов, которые идут **не дольше 90 минут**, в порядке ввода. Если таких нет, напечатайте пустой список.',
 fin='Строки `рейс:минут`, последняя строка — `END`.', fout='Список рейсов в квадратных скобках, как печатает `print(список)`.',
 pre='',
 inputs=[['Москва-Тула:80','Москва-Казань:720','Москва-Тверь:90','END'],['END'],['А-Б:100','В-Г:91','END'],['Д-Е:30','Ж-З:45','И-К:10','END'],['Л-М:90','END']],
 sol="fast = []\n\nwhile True:\n    line = input()\n    if line == 'END':\n        break\n    trip, minutes = line.split(':')\n    if int(minutes) <= 90:\n        fast.append(trip)\n\nprint(fast)\n",
 hint='Список создайте до цикла. Строку режьте по двоеточию: `trip, minutes = line.split(":")`. Время — строка, нужен `int`. «Не дольше» — это `<=`.',
 idea='Читаем строки в бесконечном цикле, на слове `END` выходим через `break`, остальное разбираем и фильтруем.',
 steps=['`fast = []` создаём **до** цикла, иначе список обнулялся бы на каждой строке.','`while True:` — читаем, пока сами не прервём цикл.','`line == "END"` → `break`: выходим, не обрабатывая слово `END`.','`trip, minutes = line.split(":")` — две части строки в две переменные.','`int(minutes) <= 90` — «не дольше» включает ровно 90.'],
 mist=['Список создан внутри цикла — в конце останется только последний рейс.','Не сделали `int(minutes)`: сравнение строки с числом — ошибка `TypeError`.','Поставили `<`: рейс ровно на 90 минут пропадёт.']),
dict(n=3, pts=0.5, title='Список покупок', topics='split(", "), not in, append, join',
 text='В первой строке товары из списка покупок через «запятая + пробел». Во второй — новый товар.\n\nЕсли его ещё нет в списке, добавьте в конец. Затем напечатайте все товары **одной строкой через «запятая + пробел»** (без скобок и кавычек).',
 fin='Первая строка — товары через `, `. Вторая — один товар.', fout='Одна строка: товары через `, `.',
 pre='',
 inputs=[['хлеб, молоко','сыр'],['хлеб, молоко','хлеб'],['чай','кофе'],['а, б, в','а'],['яблоки','Яблоки']],
 sol="items = input().split(', ')\nnew_item = input()\n\nif new_item not in items:\n    items.append(new_item)\n\nprint(', '.join(items))\n",
 hint='Разбейте строку `split(", ")`, добавьте товар, если его нет, и склейте обратно `", ".join(...)`.',
 idea='Строка → список → при необходимости добавляем → снова строка.',
 steps=['`split(", ")` — строка → список.','`not in` + `append` — добавляем только новый товар.','`", ".join(items)` склеивает элементы через «запятая + пробел».'],
 mist=['`print(items)` печатает со скобками и кавычками.','`join` вызывают у **строки-разделителя**: `", ".join(items)`, а не `items.join(", ")`.','Регистр важен: `яблоки` и `Яблоки` — разные товары.']),
dict(n=4, pts=1, title='Дорогие товары', topics='два списка, range(len())',
 text='В первой строке названия товаров через пробел, во второй — их цены (целые числа) в том же порядке. В третьей — порог цены.\n\nНапечатайте названия товаров, цена которых **строго больше** порога, каждое с новой строки.',
 fin='Три строки: названия, цены, порог.', fout='Названия по одному на строке или пустой вывод.',
 pre='',
 inputs=[['чайник фен утюг лампа','2500 1800 3200 900','2000'],['А Б','100 200','500'],['Телефон','30000','29999'],['Х У Ф','10 20 30','20'],['Лампа Шкаф','50 90','10']],
 sol="goods = input().split()\nprices = input().split()\nlimit = int(input())\n\nfor i in range(len(goods)):\n    if int(prices[i]) > limit:\n        print(goods[i])\n",
 hint='Товары и цены лежат в двух списках, связь между ними — одинаковый номер. Переберите номера через `range(len(...))`. Цены — строки, нужен `int`.',
 idea='Идём по номерам: по номеру берём и товар, и цену, сравниваем цену с порогом.',
 steps=['`goods` и `prices` — списки **строк**; цену берём как `int(prices[i])`.','`range(len(goods))` — номера 0, 1, 2, …','`int(prices[i]) > limit` — «строго больше», то есть `>`.','Печатаем `goods[i]` — товар с тем же номером.'],
 mist=['`>=` вместо `>`: товар с ценой ровно как порог попадёт зря.','Сравнили `prices[i] > limit` без `int`: строка с числом — ошибка `TypeError`.','Напечатали `prices[i]` вместо `goods[i]`.']),
dict(n=5, pts=0.75, title='Города доставки', topics='множества, объединение',
 text='Две строки: города, в которые ездит первый курьер, и города второго (через пробел).\n\nНапечатайте, сколько **различных** городов обслуживают курьеры вместе.',
 fin='Две строки, города через пробел.', fout='Одно число.',
 pre='',
 inputs=[['Москва Тверь Тула','Тула Рязань'],['Омск','Омск'],['А Б В','Г Д'],['Сочи','Сочи Адлер Туапсе'],['Казань Уфа Пермь','Пермь Уфа Казань']],
 sol="first = set(input().split())\nsecond = set(input().split())\n\nprint(len(first | second))\n",
 hint='Превратите обе строки во множества. «Вместе, без повторов» — это объединение `|`.',
 idea='Объединение двух множеств хранит каждый город один раз, даже если он есть у обоих курьеров.',
 steps=['`set(input().split())` — строка → список → множество.','`first | second` — города хотя бы одного курьера, без повторов.','`len(...)` — сколько их.'],
 mist=['Сложили `len(first) + len(second)`: общий город посчитается дважды.','`&` вместо `|`: получатся только города, общие для обоих.','`first + second`: сложение множеств не работает, будет `TypeError`.']),
dict(n=6, pts=1.25, title='Товары в одном магазине', topics='множества, симметричная разность и пересечение',
 text='Три строки с названиями товаров через запятую **без пробела** (в названиях пробелы бывают): товары первого магазина; товары второго магазина; список желаний покупателя.\n\nНапечатайте, сколько товаров из списка желаний есть **ровно в одном** из двух магазинов.',
 fin='Три строки, товары через запятую.', fout='Одно число.',
 pre='',
 inputs=[['Чайник,Фен,Утюг','Фен,Лампа,Тостер','Фен,Лампа,Утюг,Миксер'],['А б,В г','В г','А б,В г'],['Х','Х','Х'],['Ноутбук,Мышь','Клавиатура','Мышь,Монитор'],['Стол,Стул','Стул,Шкаф','Диван']],
 sol="first = set(input().split(','))\nsecond = set(input().split(','))\nwish = set(input().split(','))\n\none = first ^ second\nprint(len(one & wish))\n",
 hint='«Ровно в одном магазине» — симметрическая разность `^`. Потом пересеките результат `&` со списком желаний.',
 idea='Сначала товары, которые есть только в одном из двух магазинов (`^`), затем оставляем только желаемые (`&`).',
 steps=['Разделитель — запятая без пробела: `.split(",")`. Без аргумента названия с пробелами разорвутся.','`first ^ second` — товары, которые есть в одном магазине, но не в обоих.','`one & wish` — из них только желаемые.','`len(...)` — сколько их.'],
 mist=['`|` вместо `^`: посчитаются и товары, которые есть в обоих магазинах.','`split()` вместо `split(",")`: «А б» разорвётся на два товара.','Пересекли `first & second & wish`: получатся товары из обоих магазинов — противоположное условию.']),
dict(n=7, pts=0.75, title='Недорогие товары', topics='словарь, перебор ключей',
 text='В окне задан словарь `price`: товар → цена. Вводится предельная цена (целое число).\n\nНапечатайте товары, цена которых **не больше** предельной, каждый с новой строки, в порядке словаря. Если таких нет, ничего не печатайте.',
 fin='Одна строка — предельная цена (целое число).', fout='Названия по одному на строке или пустой вывод.',
 pre="price = {'хлеб': 50, 'молоко': 90, 'сыр': 400, 'чай': 150, 'сахар': 80, 'кофе': 600}",
 inputs=[['100'],['50'],['500'],['10'],['600']],
 sol="limit = int(input())\n\nfor item in price:\n    if price[item] <= limit:\n        print(item)\n",
 hint='Цикл `for item in price` перебирает **ключи** (товары). Цена берётся как `price[item]`. Введённый порог — строка, нужен `int`.',
 idea='Идём по товарам и печатаем те, у которых цена не больше порога.',
 steps=['`limit = int(input())` — цены в словаре числа, значит и порог нужно сделать числом.','`for item in price:` — переменная `item` по очереди получает каждый товар.','`price[item] <= limit` — «не больше», то есть `<=`.','Печатаем `item`, а не цену.'],
 mist=['Забыли `int(...)`: сравнение `50 <= "100"` — ошибка `TypeError`.','`<` вместо `<=`: товар с ценой ровно как порог пропадёт.','Напечатали `price[item]`: получится цена вместо названия.']),
dict(n=8, pts=1.25, title='Курьеры с хорошей средней', topics='словарь списков, sum / len',
 text='В окне задан словарь `couriers`: курьер → список числа доставок за пять дней. Вводится порог.\n\nНапечатайте курьеров, у которых **среднее** число доставок в день **строго больше** порога, каждого с новой строки, в порядке словаря.',
 fin='Одна строка — порог (целое число).', fout='Имена курьеров по одному на строке или пустой вывод.',
 pre="couriers = {'Аня': [10, 12, 8, 11, 9], 'Борис': [5, 7, 6, 4, 8], 'Вера': [15, 14, 16, 12, 13], 'Глеб': [9, 10, 10, 9, 12]}",
 inputs=[['10'],['6'],['14'],['0'],['20']],
 sol="limit = int(input())\n\nfor name in couriers:\n    average = sum(couriers[name]) / len(couriers[name])\n    if average > limit:\n        print(name)\n",
 hint='Среднее — это `sum(список) / len(список)`. Посчитайте его для каждого курьера и сравните с порогом.',
 idea='Для каждого ключа берём список, делим сумму на длину и сравниваем среднее с порогом.',
 steps=['`couriers[name]` — список доставок курьера.','`sum(...)` — сумма, `len(...)` — количество дней; `/` даёт среднее.','`average > limit` — строго больше порога.','Печатаем `name`, а не среднее.'],
 mist=['Забыли разделить на `len(...)`: сравнится сумма, а не среднее.','Использовали `//` вместо `/`: среднее округлится вниз, и граница сдвинется.','`>=` вместо `>`: курьер со средним ровно как порог попадёт зря.'],
 trace='Аня: 10 + 12 + 8 + 11 + 9 = 50, делим на 5 → 10. Борис: 5 + 7 + 6 + 4 + 8 = 30 → 6. Вера: 70 → 14. Глеб: 50 → 10. При пороге 10 строго больше только у Веры.'),
dict(n=9, pts=1.5, title='Вагоны по местам', topics='цикл, целочисленное деление',
 text='Места в поезде пронумерованы подряд: в первом вагоне места с 1 по N, во втором с N + 1 по 2N и так далее.\n\nПервая строка — номера мест через пробел. Вторая — N, число мест в вагоне. Напечатайте через пробел номера вагонов для этих мест в том же порядке.',
 fin='Две строки: номера мест, число мест в вагоне.', fout='Номера вагонов через пробел.',
 pre='',
 inputs=[['1 36 37 72 73','36'],['100','36'],['216 217','36'],['5 20 35','36'],['4 5 8 9','4']],
 sol="seats = input().split()\nsize = int(input())\n\ncars = []\nfor seat in seats:\n    cars.append((int(seat) - 1) // size + 1)\n\nprint(*cars)\n",
 hint='Номер вагона для места `s` — `(s - 1) // N + 1`. Список номеров соберите через `append` и распечатайте `print(*список)`.',
 idea='Для каждого места считаем номер вагона по формуле и складываем номера в список.',
 steps=['`int(seat)` — места нужны числами.','`(int(seat) - 1) // size + 1`: место 36 при N = 36 даёт 35 // 36 = 0, вагон 1; место 37 даёт 36 // 36 = 1, вагон 2.','`cars = []` до цикла, `append` внутри.','`print(*cars)` печатает элементы через пробел.'],
 mist=['`int(seat) // size + 1` без `- 1`: последнее место вагона уйдёт в следующий.','Забыли `int`: `-` и `//` со строкой — ошибка.','`print(cars)` печатает скобки и запятые.'],
 trace='Проверка при N = 36: место 36 → 35 // 36 + 1 = 1. Место 37 → 36 // 36 + 1 = 2. Место 72 → 71 // 36 + 1 = 2. Место 73 → 72 // 36 + 1 = 3.'),
dict(n=10, pts=1.5, title='Продажи по товарам', topics='while True, словарь-накопитель, сортировка',
 text='Вводятся строки вида `товар,количество` (количество — целое число), пока не будет введено слово `END`. Один товар может встретиться несколько раз.\n\nНапечатайте все товары в алфавитном порядке, каждый с новой строки, в виде `товар количество` (суммарное). В последней строке напечатайте общее количество проданного по всем товарам.',
 fin='Строки `товар,количество`, последняя строка — `END`.', fout='Строки `товар количество`, затем одно число.',
 pre='',
 inputs=[['чай,30','кофе,20','чай,25','сахар,5','END'],['мёд,7','END'],['б,10','а,1','б,2','END'],['Х,100','У,50','У,60','END']],
 sol="totals = {}\n\nwhile True:\n    line = input()\n    if line == 'END':\n        break\n    item, count = line.split(',')\n    if item in totals:\n        totals[item] += int(count)\n    else:\n        totals[item] = int(count)\n\nfor item in sorted(totals):\n    print(item, totals[item])\n\nprint(sum(totals.values()))\n",
 hint='Копите суммы в словаре, как в предыдущих задачах, а после цикла напечатайте `sorted(totals)` и `sum(totals.values())`.',
 idea='Сначала собираем словарь «товар → сумма», потом печатаем его по алфавиту и в конце общую сумму.',
 steps=['`totals = {}` — до цикла.','Если товар уже есть в словаре, прибавляем: `totals[item] += int(count)`, иначе создаём запись.','`sorted(totals)` — ключи по алфавиту.','`print(item, totals[item])` — через пробел.','`sum(totals.values())` — сумма всех значений словаря, печатаем после цикла.'],
 mist=['Забыли `sorted`: порядок будет порядком добавления.','Напечатали сумму внутри цикла: она повторится на каждой строке.','Забыли `int(count)`: строки склеиваются, а не складываются.'],
 trace='Чай: 30, затем 25 → 55. Кофе: 20. Сахар: 5. По алфавиту: `кофе`, `сахар`, `чай`. Общая сумма 55 + 20 + 5 = 80.'),
]
